{
  "name": "opencode-discord-manager",
  "version": "0.3.0",
  "description": "Full Discord bot plugin for opencode — relay channels, DM auto-mode, server management tools, book search",
  "keywords": [
    "opencode",
    "discord",
    "plugin",
    "ai",
    "bridge",
    "chat"
  ],
  "license": "MIT",
  "author": "spaceym78",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/spaceym78/opencode-discord-manager.git"
  },
  "bugs": {
    "url": "https://github.com/spaceym78/opencode-discord-manager/issues"
  },
  "homepage": "https://github.com/spaceym78/opencode-discord-manager#readme",
  "type": "module",
  "main": "src/index.ts",
  "bin": {
    "opencode-discord-setup": "./scripts/setup.sh"
  },
  "scripts": {
    "postinstall": "node scripts/copy-plugin.cjs",
    "setup": "bash scripts/setup.sh"
  },
  "dependencies": {
    "@opencode-ai/plugin": "^0.1.0",
    "discord.js": "^14.18.0"
  },
  "engines": {
    "node": ">=18"
  },
  "files": [
    "src/",
    "scripts/",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  }
}
